@import "@fontsource-variable/outfit";
@import "@fontsource-variable/newsreader/opsz.css";

/* Light (faithful): ivory #f8f6f2 page, forest #284849 for headings, primary buttons and the
   plans band, neutral #333 body copy, sage #4a786a soft buttons and links, clover #6fb29f
   hairlines and dots, mint #c1e5db announcement bar and "us" column, seafoam #ebf2f0 bands,
   beige #eadec8 wash behind the clinician section and the hero text, ochre #bf7e3d price notes. */
:root {
  --background: #f8f6f2;
  --foreground: #333333;
  --card: #eadec8;
  --card-foreground: #333333;
  --popover: #fcfbfa;
  --popover-foreground: #333333;
  --primary: #284849;
  --primary-foreground: #fcfbfa;
  --secondary: #4a786a;
  --secondary-foreground: #fcfbfa;
  --muted: #ebf2f0;
  --muted-foreground: #737373;
  --accent: #c1e5db;
  --accent-foreground: #284849;
  --destructive: #ab373d;
  --destructive-foreground: #fcfbfa;
  --border: #6fb29f;
  --input: #c9d3d0;
  --ring: #4a786a;
  --highlight: #bf7e3d;
  --highlight-foreground: #132d2e;
  --glow: #6fb29f;
  --chart-1: #284849;
  --chart-2: #6fb29f;
  --chart-3: #bf7e3d;
  --chart-4: #6483a0;
  --chart-5: #b16960;
  --sidebar: #fcfbfa;
  --sidebar-foreground: #333333;
  --sidebar-primary: #284849;
  --sidebar-primary-foreground: #fcfbfa;
  --sidebar-accent: #ebf2f0;
  --sidebar-accent-foreground: #284849;
  --sidebar-border: #d5e3df;
  --sidebar-ring: #4a786a;

  --typeface-body: "Outfit Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Newsreader Variable", ui-serif, Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 69rem;
  --page-gutter: 1.25rem;
  --section-y: 7.5rem;
}

/* Dark sibling, and the palette of the nav bar and footer (which carry the .dark class):
   forest #284849 ground, deep sea #132d2e for the nav and sunken bands, bone text and
   buttons, clover for soft buttons and hairlines, peach #ebcfb8 as the sparing warm note. */
.dark {
  --background: #284849;
  --foreground: #fcfbfa;
  --card: #34595a;
  --card-foreground: #fcfbfa;
  --popover: #1d3b3c;
  --popover-foreground: #fcfbfa;
  --primary: #fcfbfa;
  --primary-foreground: #284849;
  --secondary: #6fb29f;
  --secondary-foreground: #132d2e;
  --muted: #132d2e;
  --muted-foreground: #b4c7c2;
  --accent: #3a6463;
  --accent-foreground: #c1e5db;
  --destructive: #e0787d;
  --destructive-foreground: #132d2e;
  --border: #6fb29f;
  --input: #4f7473;
  --ring: #6fb29f;
  --highlight: #ebcfb8;
  --highlight-foreground: #132d2e;
  --glow: #6fb29f;
  --chart-1: #c1e5db;
  --chart-2: #6fb29f;
  --chart-3: #ddb27f;
  --chart-4: #85aed4;
  --chart-5: #f5b3aa;
  --sidebar: #1d3b3c;
  --sidebar-foreground: #fcfbfa;
  --sidebar-primary: #6fb29f;
  --sidebar-primary-foreground: #132d2e;
  --sidebar-accent: #34595a;
  --sidebar-accent-foreground: #fcfbfa;
  --sidebar-border: #3d6463;
  --sidebar-ring: #6fb29f;
}
